using M=std::array<float,16>; M I(){M r{};r[0]=r[5]=r[10]=r[15]=1;return r;} M mul(const M&a,const M&b){M r{};for(int c=0;c<4;c++)for(int x=0;x<4;x++)for(int k=0;k<4;k++)r[c*4+x]+=a[k*4+x]*b[c*4+k];return r;} M tr(float x,float y,float z){M r=I();if(x==-1.9f&&y==-1.2f&&z==0){x=second_pos[0];y=second_pos[1];z=second_pos[2];}r[12]=x;r[13]=y;r[14]=z;return r;} M sc(float x,float y,float z){if(x==.42f&&y==.42f&&z==.42f)x=y=z=second_scale;M r{};r[0]=x;r[5]=y;r[10]=z;r[15]=1;return r;} M rx(float a){M r=I();float c=cos(a+pi/2),s=sin(a+pi/2);r[5]=c;r[6]=s;r[9]=-s;r[10]=c;return r;} M ry(float a){M r=I();float c=cos(a),s=sin(a);r[0]=c;r[2]=-s;r[8]=s;r[10]=c;return r;} M rz(float a){M r=I();float c=cos(a),s=sin(a);r[0]=c;r[1]=s;r[4]=-s;r[5]=c;return r;}
